const fn = new Function(code + "\nreturn { resolveTokens, applyTheme, motionPolicy };");
const { resolveTokens, applyTheme, motionPolicy } = fn();
const out = resolveTokens([
  { "--color-bg": "white", "--color-fg": "black" },
  { "--color-bg": "navy" },
]);
if (out["--color-bg"] !== "navy") throw new Error("Later scopes win per token.");
if (out["--color-fg"] !== "black") throw new Error("Tokens absent from later scopes survive.");
const input = { a: 1 };
resolveTokens([input]);
if (input.a !== 1 || Object.keys(input).length !== 1) throw new Error("Input scopes must not be mutated.");

const fn = new Function(code + "\nreturn { resolveTokens, applyTheme, motionPolicy };");
const { resolveTokens, applyTheme, motionPolicy } = fn();
const s = { mode: "system", explicit: false };
const set = applyTheme(s, { type: "set", mode: "dark" });
if (set.mode !== "dark" || set.explicit !== true) throw new Error("set makes the mode explicit.");
if (s.mode !== "system" || s.explicit !== false) throw new Error("The input state must not be mutated.");
const reset = applyTheme(set, { type: "reset" });
if (reset.mode !== "system" || reset.explicit !== false) throw new Error("reset returns to the system default.");

const fn = new Function(code + "\nreturn { resolveTokens, applyTheme, motionPolicy };");
const { resolveTokens, applyTheme, motionPolicy } = fn();
if (motionPolicy(true, "full") !== "full") throw new Error("An explicit 'full' choice beats the OS preference.");
if (motionPolicy(true, "reduced") !== "reduced") throw new Error("Explicit reduced always reduces.");
if (motionPolicy(true, "system") !== "reduced") throw new Error("System + prefers-reduced-motion reduces.");
if (motionPolicy(false, "system") !== "full") throw new Error("System without the OS preference is full.");
